from spell_evals_base import E, s

def x(name, ev):
    r, g, _ = E[name]
    s(name, r, g, ev)

x('Interposing Earth', "Interposing Earth raises a small barrier as a reaction, giving standard cover against one Strike or one damaging area effect and reducing the damage if it still lands. It is a modest defensive tool. It competes with Reactive Strike for Cyrus's reaction, and from level 6 Reactive Strike usually does more to protect the party by punishing enemies that move or act in his reach.")
x('Runic Weapon', "Runic Weapon turns a weapon into a +1 striking weapon for a minute, rising to +2 greater striking at rank 6. Aspera already carries fundamental runes on schedule, so the spell only helps a backup weapon or an ally who has fallen behind on runes. It doesn't need a place in Cyrus's spellbook.")
x('Acid Arrow', "Acid Arrow is a legacy attack spell that deals acid damage plus persistent acid on Aspera's attack roll. It only heightens every two ranks, so as a heightened payload it falls behind Blazing Bolt, which gains damage every rank. It is only worth learning if Cyrus specifically wants persistent acid against something that regenerates.")
x('Stupefy', "Stupefy imposes stupefied, which makes enemy spellcasting less reliable and lowers Will and mental checks. Its success effect only lasts until the start of Cyrus's next turn, and both Befuddle and Improvise Strategy cover the same job while offering more. It is rarely worth a slot.")
x('Water Breathing', "Water Breathing lets up to five creatures breathe underwater for an hour, longer when heightened. It solves a specific problem completely, but only when the adventure takes the party underwater. A scroll, bought when the party knows water is ahead, is the right way to carry it.")
x('Embed Message', "Embed Message hides a 25-word message on an object or willing creature that plays when a chosen trigger occurs. It is a roleplay tool for dead drops, warnings and coded signals. It rarely needs one of Cyrus's prepared slots, but it fits Aspera's theme of things that speak across time.")
x('Earthbind', "Earthbind forces a flying creature to descend safely and can keep it grounded for a round or a minute on a failed save. It is a strong answer to wyverns, harpies and other flyers that would otherwise stay out of Aspera's reach. A scroll is the right choice, bought when the party expects flying enemies.")
x('Scouting Eye', "Scouting Eye creates an invisible eye that Cyrus can move up to 30 feet each round while he sustains it. It is more flexible than Clairvoyance when there is a corridor or route to follow. Because the party usually has time between fights, it is a good way to scout the next encounter before committing.")
x('Haunting Hymn', "Haunting Hymn is a sonic cantrip with a basic Fortitude save that can deafen on a critical failure. Frostbite already gives Cyrus a Fortitude cantrip with better damage scaling, so this offers little as a familiar cantrip. Guidance and Read the Air are better uses of the two familiar choices.")
x('Wash Your Luck', "Wash Your Luck lets Cyrus cancel a misfortune effect on one later roll. Misfortune effects are uncommon, so the cantrip rarely does anything. It is not worth one of the familiar's two cantrips.")
x('Know the Way', "Know the Way tells Cyrus which direction is north and where a recently visited location lies. It is pure exploration flavour, and the party is unlikely to need it often in a campaign with established routes and towns.")
x('Bane', "Bane gives enemies in an emanation a −1 status penalty to attacks if they fail a Will save, and sustaining it widens the area. The Cleric can also cast it from the divine list, and sustaining it each turn competes with Cyrus's recharge actions. A scroll is only worth it on days Yara doesn't prepare it.")
x('Sanctuary', "Sanctuary forces any creature trying to attack the protected creature to succeed at a Will save first. It is a useful emergency scroll for protecting a downed or vulnerable ally from follow-up attacks while Yara heals. It ends if the protected creature acts with hostility.")
x('Liberating Command', "Liberating Command lets a grabbed, immobilised or restrained ally immediately use a reaction to attempt to Escape. It costs only one action and has a 60-foot range, which makes it a cheap rescue tool. A wand is attractive because it can be used every day without planning.")
x('Ill Omen', "Ill Omen makes the target roll its next attack or skill check twice and take the worse result, or every one for a round on a critical failure. It is a quick way to blunt a boss's most dangerous attack before it acts. It depends on a Will save against Cyrus's DC.")
x('Lose the Path', "Lose the Path is a reaction that makes a striding creature treat its movement as difficult terrain, or lets Cyrus redirect it on a critical failure. It can stop a charge, but it competes with Reactive Strike, which usually achieves more with the same reaction.")
x('Phantom Pain', "Phantom Pain deals mental damage plus persistent mental damage and sickens the target. Its damage is low for a slot of its rank, and mental immunity is common, so Cyrus's arcane payloads are better choices.")
x('Spirit Link', "Spirit Link transfers a few Hit Points from Cyrus to an ally at the start of each of his turns for 10 minutes. It can help keep a front-line ally standing through a long fight. It drains Cyrus's own Hit Points, so it works best when he is not taking much damage himself.")
x('Calm', "Calm can stop creatures in an area from using hostile actions if they fail their save, and suppresses emotion effects on them. It is a useful scroll for ending a brawl the party would rather talk their way out of. Any hostility towards an affected creature ends the effect on a normal failure.")
x('Silence', "Silence makes one willing creature soundless, and at rank 4 it creates a 10-foot aura that silences everything inside, including verbal spellcasting. It is an excellent infiltration scroll for the party's stealthiest member, and the rank-4 version can also stop enemy casters in the aura.")
x('Cleanse Affliction', "Cleanse Affliction reduces the stage of a curse, disease or poison, and heightened versions attempt to counteract it. Yara shares this spell, so Cyrus only needs a scroll as backup once Yara's slots are spent.")
x('Sure Footing', "Sure Footing counteracts clumsy, grabbed or paralysed, and at rank 4 also immobilised, slowed and restrained. It is a useful backup to Clear Mind for freeing an ally from a disabling condition, and a scroll covers the occasional need.")
x('Paranoia', "Paranoia makes the target treat everyone as a threat, which can turn it against its allies. The effect is hard to predict or control and depends on Cyrus's spell DC, so it is not a reliable tool.")
x('Augury', "Augury takes 10 minutes and gives a vague good, bad, mixed or nothing answer about a course of action in the next 30 minutes, with a secret chance of a false nothing. The information is too limited to justify the cost for most decisions.")
x('Spiritual Armament', "Spiritual Armament flings a spiritual copy of a weapon and can be sustained to attack again. Cyrus could deliver it through Striker's Scroll, but his arcane attack payloads deal more damage and don't need sustaining.")
x('Status', "Status lets Cyrus track an ally's direction, distance and conditions until his next daily preparations. It is useful when the party splits up for scouting or infiltration, but it rarely needs to be carried.")
x('Heroism', "Heroism grants a +1 status bonus to attacks, saves, skills and Perception for 10 minutes, rising at ranks 6 and 9. Yara can cast it from the divine list, so Cyrus's scroll or wand mainly frees Yara's slots for healing and other spells.")
x('Hypercognition', "Hypercognition makes up to six Recall Knowledge checks as part of a single one-action cast. For a Lore-heavy scholar like Cyrus, that identifies every enemy in a fight at once, which tells the whole party which defences to target. A wand gives this every day, making it one of the best occult purchases for him.")
x('Defensive Prescience', "Defensive Prescience is a reaction that protects a familiar from an attack. It only matters if the Witch familiar is likely to be targeted, which is rare if it stays out of the fight.")
x('Begone', "Begone pushes a creature up to 30 feet on a failed Fortitude save for one action, and it deals damage if the creature hits a wall. It is a cheap way to move an enemy off a downed ally or into a hazard.")
x('Strength of Mind', "Strength of Mind gives a status bonus against mental effects and effects that hinder movement for 10 minutes. It is a narrow defensive buff that the party rarely needs.")
x('Focusing Hum', "Focusing Hum lowers the flat check for stupefied casters and stops confused creatures from attacking. It is far too narrow to be worth carrying.")
x('Infectious Melody', "Infectious Melody forces affected enemies to sing in order to speak, which mainly hampers their communication. It has little effect in most fights and is not worth carrying.")
x('Read Omens', "Read Omens takes 10 minutes and gives a cryptic clue about an event in the coming week. It offers flavour and occasional story hooks rather than reliable information.")
x('Honeyed Words', "Honeyed Words gives a +4 status bonus to Lie and adds Cyrus's level even if untrained. It is useful for an infiltration where he must talk his way past guards, though his Charisma is not high.")
x('Strange Geometry', "Strange Geometry creates cubes of illusory terrain that slow creatures who believe them. It takes three actions and depends on Cyrus's spell DC, so other control spells are better choices.")
x('Inevitable Disaster', "Inevitable Disaster deals 55 damage with a basic Fortitude save after a secret delay of 1d4 rounds, wherever the target is. It is reliable damage against a single boss that is hard to reach, though Cyrus can't control exactly when it lands.")
x('Death Ward', "Death Ward is a legacy spell that grants void resistance 10 and a bonus against death and void effects for 10 minutes. It is valuable for the front line or Cyrus during an undead-heavy arc, and a scroll covers the specific fight.")
x('Shadow Blast', "Shadow Blast lets Cyrus choose the damage type and area shape, but each target chooses whether to save with Reflex or Will. That lets every creature use its stronger save, which makes it unreliable.")
x('Zealous Conviction', "Zealous Conviction grants 12 temporary Hit Points and a +2 bonus to Will saves against mental effects to up to ten allies for 10 minutes. With rests between fights, it is an excellent buff to cast just before a big encounter. A wand makes it available every day.")
x('Scintillating Safeguard', "Scintillating Safeguard is a reaction that gives up to five allies resistance 10 against the initial damage of a triggering effect. It is a strong counter to an enemy's big area spell or breath weapon, but it uses Cyrus's reaction.")
x('Spirit Blast', "Spirit Blast deals heavy spirit damage to one creature with a basic Fortitude save, which affects incorporeal targets fully. Cyrus's arcane attack payloads usually deal comparable damage on Aspera's stronger attack roll.")
x('Blanket of Stars', "Blanket of Stars grants a bonus to Stealth and can make Cyrus invisible while still under a starry sky. It is too narrow to carry for most adventures.")
x('Ethereal Jaunt', "Ethereal Jaunt lets Cyrus move onto the Ethereal Plane for a minute, passing through walls and avoiding most material effects. It is a strong infiltration and escape scroll.")
x('Visions of Danger', "Visions of Danger fills an area with illusory monsters that deal mental damage to creatures inside it. It takes three actions and can be disbelieved, so other area spells are more reliable.")
x('Orb of Twisting Fate', "Orb of Twisting Fate makes the target waste its first action each turn on a failed save. It depends heavily on Cyrus's spell DC, so it is weak compared with arcane options at the same rank.")
x('Spirit Song', "Spirit Song deals spirit damage in an area and prevents reactions on a failure. It can reach incorporeal creatures hiding in walls, which gives it a niche against hauntings.")
x('Spiritual Epidemic', "Spiritual Epidemic inflicts lasting enfeebled and stupefied conditions on a failed save and spreads to anyone who casts divine or occult spells on the target. It is strong against an enemy priest, but it relies on Cyrus's spell DC.")
x('Overwhelming Presence', "Overwhelming Presence forces any number of creatures to spend actions paying tribute to Cyrus, even on a successful save. It can tie up a whole group, but it relies on his spell DC at the highest rank.")
x('Unfathomable Song', "Unfathomable Song inflicts random debuffs on up to five targets each round it is sustained. Sustaining it competes with Cyrus's recharge actions, and the results are unpredictable.")

# fuller evaluations
E['Paralyze'] = (E['Paralyze'][0], E['Paralyze'][1], "Paralyze is one of the strongest single-target payloads at rank 3 against an enemy at or below Cyrus's level: stunned 1 on a success costs it an action even when it saves, and a failure paralyses it, which makes it off-guard and helpless for the party's attacks. Through Spellstrike the Will save happens even if the Strike misses. The incapacitation trait makes it much weaker against a higher-level boss, where a failure is treated as a success, so it is best saved for the strongest of a group of lower-level enemies. Its 30-foot range means it can also be cast normally on a caster outside his reach.")
E['Ghostly Weapon'] = (E['Ghostly Weapon'][0], E['Ghostly Weapon'][1], "Incorporeal enemies resist almost everything Aspera does unless the weapon has ghost touch, so this spell decides whether Cyrus can contribute in a fight against spirits or haunts at all. Five minutes covers a whole encounter, and it can go on an ally's weapon instead. From level 11 it is a studious spell, so casting it also lets him enter Arcane Cascade as a free action, though it still uses a slot. Because it is only needed in specific fights, a scroll read before the fight is often the better way to carry it.")
E['Noise Blast'] = (E['Noise Blast'][0], E['Noise Blast'][1], "A Fortitude area spell is valuable because most of Cyrus's area damage targets Reflex, and agile enemies tend to have high Reflex. Through Expansive Spellstrike its 10-foot burst can be placed on a corner of the target, and a critical failure stuns. Its damage is lower than the best Reflex options at the same rank, so it is the choice when Analysis shows a group with weak Fortitude rather than a default.")
E['Dimensional Drop'] = (E['Dimensional Drop'][0], E['Dimensional Drop'][1], "Dimensional Drop deals falling damage and knocks the target prone, so it is a Reflex payload that also sets up Laughing Shadow's damage and Reactive Strike when the target Stands. It only works on a creature standing on the ground, which rules out flyers, and its damage at rank 2 is modest. It is worth carrying as a scroll or preparing on days when Cyrus expects grounded brutes, where the prone condition matters more than raw damage.")
E['Mirror Image'] = (E['Mirror Image'][0], E['Mirror Image'][1], "Mirror Image makes three in four attacks that would hit Cyrus strike an image instead, and misses that don't critically fail also destroy an image. Against an enemy making several weapon attacks a turn it can prevent more damage than a healing spell restores, and it lasts the whole fight. It does nothing against area spells or saves, and it costs two actions on a turn without a Spellstrike, so it belongs in the opening round against a known melee threat, ideally from a wand or scroll rather than a slot.")
E['Grim Tendrils'] = (E['Grim Tendrils'][0], E['Grim Tendrils'][1], 'Grim Tendrils is a Fortitude line with persistent bleed, which makes it one of the few rank 1 line spells for Expansive Spellstrike and Sprinting Spellstrike. Its damage is small, it only affects living creatures, and Lightning Bolt replaces it as his line payload from level 5. It is a reasonable rank 1 choice early on but not worth a slot later.')

# purple ratings kept for genuine outliers; reliability-adjusted damage
E['Sure Strike'] = ('000500', E['Sure Strike'][1], E['Sure Strike'][2])
E['Invisibility'] = ('000435', E['Invisibility'][1], E['Invisibility'][2])
E['Fly'] = ('000355', E['Fly'][1], E['Fly'][2])
E['Wall of Stone'] = ('050043', E['Wall of Stone'][1], E['Wall of Stone'][2])
E['True Target'] = ('000500', E['True Target'][1], E['True Target'][2])
E['Disappearance'] = ('000555', E['Disappearance'][1], E['Disappearance'][2])
E['Quandary'] = ('050000', E['Quandary'][1], E['Quandary'][2])
E['Foresight'] = ('000503', E['Foresight'][1], E['Foresight'][2])
E['Remake Physiology'] = ('045030', E['Remake Physiology'][1], E['Remake Physiology'][2])
E['Disintegrate'] = ('500003', 'ABD', "Disintegrate deals 12d10 untyped damage on Aspera's attack roll, but the target still gets a basic Fortitude save, and a critical hit only worsens that save by one degree. Against a level-14 boss at level 12, with Sure Strike, it averages about 25 spell damage against a moderate Fortitude save, where Blood Feast heightened to rank 6 averages about 37 with no save; it only pulls level against low Fortitude. Its strengths are the ceiling, since a critical hit against a failed save doubles to around 130 damage, enemies whose Fortitude has been lowered by Blister Bomb or Eagle's Cry, and its utility: it destroys a wall of force or a 10-foot cube of matter outright, and a creature it reduces to 0 Hit Points is left as dust.")
E['Chain Lightning'] = ('500000', 'ACD', 'Through Spellstrike, Chain Lightning only hits the struck creature, but that is still 8d12 on a save that happens even if the Strike misses, which makes it as good as Disintegrate on an average turn and more reliable. Cast normally it is one of the best area options Cyrus has: it arcs from creature to creature within 30 feet, skips allies, and has a 500-foot range. The chain stops when any target critically succeeds, so it is weaker against groups with high Reflex. It is the more dependable rank-6 damage spell; Disintegrate is the one to pick when he can set up a hit.')
E['Living Thunderbolt'] = ('502450', 'SCD', "Living Thunderbolt does more for this build than any other rank-6 spell. For a minute Cyrus flies at 60 feet, resists electricity, escapes most grabs automatically, and can move through creatures, each taking 4d12 electricity with a basic Reflex save once per round and dazzled on a failure. That damage repeats every round he moves through enemies, with no further actions spent, and it keeps Aspera in his hands because it is not a battle form. Combined with Sprinting Spellstrike it becomes his strongest turn: he flies the line through a group, every creature on the path takes Living Thunderbolt's damage and the line spell's damage, and the target also takes the Strike. The cost is two actions on a turn without a Spellstrike, so it is cast before contact or on a turn spent closing distance.")
E['Blazing Fissure'] = ('442000', 'SCD', 'Blazing Fissure is the best line spell for Sprinting Spellstrike from rank 5. Each creature on the ground along the line takes 4d6 bludgeoning and 6d6 fire, and on a failed save falls prone, which makes it off-guard for Laughing Shadow and the party and costs it an action to Stand into Reactive Strike. With Expansive Spellstrike the line follows his path, and with Living Thunderbolt active every creature he passes also takes its electricity damage, so one turn can damage and floor a whole file of enemies. Flying creatures are unaffected, and it uses a full Reflex save rather than a basic one, so a critical success means no damage. Lightning Bolt heightened to the same rank does slightly more damage with no prone, so the choice depends on whether control or raw damage matters more.')

# restored ratings and category corrections (base rank); heightened changes live in heightened.py
E['Sure Strike'] = ('000600', E['Sure Strike'][1], E['Sure Strike'][2])
E['Invisibility'] = ('000436', E['Invisibility'][1], E['Invisibility'][2])
E['Fly'] = ('000365', E['Fly'][1], E['Fly'][2])
E['Wall of Stone'] = ('060043', E['Wall of Stone'][1], E['Wall of Stone'][2])
E['True Target'] = ('000600', E['True Target'][1], E['True Target'][2])
E['Disappearance'] = ('000656', E['Disappearance'][1], E['Disappearance'][2])
E['Quandary'] = ('060000', E['Quandary'][1], E['Quandary'][2])
E['Foresight'] = ('000603', E['Foresight'][1], E['Foresight'][2])
E['Remake Physiology'] = ('046030', E['Remake Physiology'][1], E['Remake Physiology'][2])
E['Synesthesia'] = ('036000', E['Synesthesia'][1], E['Synesthesia'][2])
E['Slow'] = ('054000', E['Slow'][1], E['Slow'][2])
E['Haste'] = ('000550', E['Haste'][1], E['Haste'][2])
E['Dehydrate'] = ('202000', 'ACC', "Dehydrate is weak at rank 1 and one of the best damage spells Cyrus can heighten. Every two ranks it adds 3d6 persistent fire, 10 feet of range and 5 feet of burst, so at rank 5 it is a 15-foot burst of 7d6 persistent fire on a basic Fortitude save, and each affected creature also saves every turn against being enfeebled. Persistent damage keeps landing each round until the creature recovers, so its real damage is usually two or three times the listed dice, and it targets Fortitude, which complements his Reflex-heavy area list. Through Expansive Spellstrike the burst centres on a corner of the target's space, so it needs the same care as any burst to spare Cyrus and his allies. Creatures immune to fire or with fast healing blunt it, and water and plant creatures fare worse. Learn it early and cast it from his higher slots.")
E['Haste'] = (E['Haste'][0], E['Haste'][1], E['Haste'][2] + " At rank 7 it targets six creatures, so one cast gives the whole party an extra action every turn for a minute.")

# reaction spells: Cyrus holds Aspera in two hands, so a reaction scroll or wand needs an Interact to draw it
# beforehand and another to regrip afterwards, and only pays off if the trigger happens while it is in hand.
# Prepared slots and the fused stave (from level 8) are the routes that work.
_HANDS = (" A scroll or wand is a poor way to carry it: Cyrus would have to draw it on his turn, give up the grip on Aspera, "
          "hope the trigger comes before his next turn and then spend another action to regrip. If he wants it from an item, "
          "the fused stave is the only practical route, because Fused Staff lets him cast from Aspera while holding it in both hands.")
E['Gentle Landing'] = ('000003', 'BCD', "Gentle Landing stops all damage from a fall for anyone within 60 feet, which turns a lethal drop into nothing. Most falls happen outside combat, when Cyrus is climbing, crossing a bridge or standing near a ledge, so on days like that he can prepare it, or hold the scroll in hand while the party climbs. That is why the scroll is still usable, unlike most reaction scrolls. A wand is worse, because it has to be in hand at the moment of the fall and is no cheaper per use for a spell this rarely needed.")
E['Interposing Earth'] = ('000300', 'CDD', "Interposing Earth gives standard cover against one Strike or one damaging area effect, which is a +2 to AC or Reflex for that effect, and takes 2 damage off if it still hits. Before level 6 Cyrus has nothing else to spend his reaction on, so a prepared copy is a fair use of a spare rank 1 slot. From level 6 Reactive Strike competes for the same reaction and usually does more, because it punishes enemies that move or cast in his reach." + _HANDS)
E['Lose the Path'] = ('030000', 'FDD', "Lose the Path turns an enemy's Stride into difficult terrain, which can stop a charge short, and lets Cyrus steer it on a critical failure. It is occult and primal, so he can't learn it. Even after the Witch dedication, it competes with Reactive Strike, which already punishes enemies that move through his reach." + _HANDS)
E['Blood Vendetta'] = ('220000', 'CDD', "Blood Vendetta makes an enemy bleed after it deals piercing, slashing or bleed damage to Cyrus. The persistent damage is decent at higher ranks, but the trigger needs him to be hit first, and Reactive Strike is usually the better use of his reaction." + _HANDS)
E['Wooden Double'] = ('000400', 'BDD', "Wooden Double turns a critical hit against Cyrus into a hit on a wooden decoy, which can save him from a boss's double-damage critical. He chooses after the critical is rolled, so it never wastes his reaction on an ordinary hit. It is worth a prepared rank 3 slot against hard-hitting single enemies where a critical could drop him." + _HANDS)
E['Defensive Prescience'] = ('000200', 'FDD', "Defensive Prescience protects a familiar from an attack. It only matters if the Witch familiar is likely to be targeted, which is rare if it stays out of the fight. It is divine and occult, so he can't learn it." + _HANDS)
E['Shadow Siphon'] = ('000400', 'CDD', "Shadow Siphon counteracts part of an enemy's damaging spell and halves its damage for every creature it affects. Against an enemy blaster it can save the whole party a large amount of damage, but it depends on a counteract check and competes with Reactive Strike for his reaction. It is worth preparing when the party knows it will face a caster with area spells." + _HANDS)
E['Unexpected Transposition'] = ('000430', 'BDD', "Unexpected Transposition swaps Cyrus with another creature within 30 feet when he is targeted by a Strike, so the attack resolves against them instead. Swapping with an enemy is the best use: the enemy gets a Will save, but on a failure it takes its own ally's attack. It competes with Reactive Strike for his reaction, so it is best prepared for fights against a single dangerous attacker." + _HANDS)
E['Scintillating Safeguard'] = ('000500', 'FDD', "Scintillating Safeguard gives up to five allies resistance 10 against the initial damage of one effect, which takes a large share off an enemy's big area spell or breath weapon. It is divine, occult and primal, so Cyrus can't learn it, but after the Witch dedication it could go on the fused stave, where he can cast it without letting go of Aspera. That is worth considering if the campaign turns towards dragons or enemy blasters." + _HANDS.replace(" If he wants it from an item, the fused stave is the only practical route, because Fused Staff lets him cast from Aspera while holding it in both hands.", ""))
E['Spell Riposte'] = ('000403', 'BDD', "Spell Riposte counteracts a targeted spell aimed at Cyrus and, on a success, sends it back at its caster. It can't affect area spells. It should be prepared when the party knows it will face a caster who relies on targeted spells such as Disintegrate or Phantasmal Killer." + _HANDS)

# reaction spells that were missing
E['Eat Fire'] = ('000202', 'C--', "Eat Fire is a reaction cantrip that gives resistance to fire damage against the triggering effect, rising by 5 every three cantrip ranks, and then lets Cyrus spend an action to breathe out a smoke cloud that makes creatures in it concealed. As a cantrip it costs no slot, but it takes one of his five prepared cantrips, which are better spent on damage and Shield. It is worth swapping in for a known fire-heavy fight.")
E['Schadenfreude'] = ('012000', 'CDD', "Schadenfreude triggers only when Cyrus critically fails a save, which happens a few times a campaign rather than every fight. When it does, the enemy is stupefied or, on a critical failure, stunned 1. It is too unreliable to take a slot over spells that work every fight." + _HANDS)
E['Hidebound'] = ('000300', 'BDD', "Hidebound gives a creature within 60 feet resistance 5 to physical damage when it is hit by a Strike, and the resistance lasts until the start of its next turn, so it also covers any further Strikes against it that turn. It rises by 3 every two ranks. On a front-liner facing a monster with several attacks it prevents a useful amount of damage, but it competes with Reactive Strike for Cyrus's reaction. It is one of the planned picks for Axuma's Awakening at 11, where it costs no slot and needs no hands." + _HANDS)
E['Warping Pull'] = ('000430', 'BDD', "Warping Pull teleports an ally up to 10 feet towards Cyrus when it is about to take damage, and gives it resistance 5 to all damage from that effect, rising by 5 every two ranks. Unlike Hidebound, it works against spells, breath weapons and other area damage as well as Strikes, and the teleport can pull an ally out of an enemy's reach or next to Cyrus for flanking. At rank 6 the resistance is 15, which is a large share of most single hits at that level. It is uncommon, so learning it needs access; Axuma's Awakening gives it at 11 without that, and it is one of the planned picks there. It competes with Reactive Strike for his reaction." + _HANDS)
E['Propulsive Breeze'] = ('000030', 'CDD', "Propulsive Breeze adds 15 feet to the end of an ally's Stride or Leap, which can get Mira or Cassius into melee in one move. It uses Cyrus's reaction on another creature's turn, so he loses Reactive Strike until his next turn, and it only extends movement in a straight line from the last 5 feet." + _HANDS)
E['Pyrefowl Rebuke'] = ('100010', 'DDD', "Pyrefowl Rebuke deals a small amount of fire damage to a creature that hits Cyrus from within 10 feet and flies him 10 feet directly away. That usually takes him out of reach of the enemy he wants to hit, which works against a reach fighter who wants enemies at 10 feet. It is uncommon and from an adventure path. Reactive Strike does more with the same reaction." + _HANDS)
E["Cloud Dragon's Cloak"] = ('000400', 'BDD', "Cloud Dragon's Cloak makes an ally hidden against the triggering ranged attack and every other ranged attack against it for a round, so each one needs a DC 11 flat check, which fails half the time. It works against ranged spell attacks too. Against archers or ranged casters it prevents more damage than Hidebound, and Cyrus casts it on another creature's turn, so it costs him nothing on his own turn. It still competes with Reactive Strike for his reaction." + _HANDS)
E['Shadow Projectile'] = ('202000', 'CDD', "Shadow Projectile triggers when an ally within 20 feet makes a ranged attack. The target is off-guard against that attack on a failed or successful Will save and takes mental damage on a failure. Theldren's, Yara's and Adrian's ranged spell attacks qualify, so it can raise one of their hits. The target then becomes immune for an hour, so it works once per enemy per fight, and it competes with Reactive Strike." + _HANDS)
E['Zephyr Slip'] = ('000020', 'DDD', "Zephyr Slip flies Cyrus 15 feet away from a creature that moves next to him. As a reach fighter he wants enemies 10 feet away, and moving 15 feet from an adjacent enemy puts him out of reach, so it usually undoes his position rather than helping it. At rank 8 it can move five allies 25 feet, which is a real escape, but Translocate and Dimensional Disappearance do that job better." + _HANDS)
E['Rebounding Barrier'] = ('000300', 'CDD', "Rebounding Barrier gives Cyrus resistance 10 against one physical damage type of the Strike that hit him, rising by 2 each rank, and deals a small amount back to the attacker. It is rare, so it needs Alex's approval, and it only protects Cyrus himself. Wooden Double handles the dangerous case, a critical hit, more completely." + _HANDS)
E['Drop Dead'] = ('000403', 'BDD', "Drop Dead triggers when an ally within 120 feet is hit, makes it appear to die and turns it invisible. That takes the ally out of the fight's targeting immediately, which can save a downed or nearly-downed ally from a follow-up attack. It is sustained, so it costs Cyrus an action each turn to keep it going, and below rank 7 it ends as soon as the ally attacks. At rank 7 it doesn't end on a hostile action, which makes it an invisibility the ally can fight from. It is uncommon, so it needs access." + _HANDS)

# reaction slot value: low-rank reactions use slots with few better uses once higher ranks arrive;
# high-rank reactions compete with action spells for valuable slots.
_LOW = (" Because it is low rank, it uses one of the slots Cyrus values least once he has higher ranks, so it is an easy"
        " addition on most days, and a prepared reaction is still useful on turns when nothing provokes Reactive Strike.")
_HIGH = (" At this rank it also costs a slot that could hold a spell he casts on his own turn, which makes it harder to"
         " justify than the lower-rank reactions.")
def _set(n, r=None, g=None, add=''):
    a, b, c = E[n]
    E[n] = (r or a, g or b, c.replace(_HANDS, '') + add + (_HANDS if _HANDS in c else ''))
_set('Interposing Earth', g='BDD', add=_LOW)
_set('Blood Vendetta', g='BDD', add=_LOW)
_set('Wooden Double', g='ADD', add=_LOW)
_set('Hidebound', r='000400', g='ADD', add=_LOW)
_set('Warping Pull', g='ADD', add=_LOW)
_set('Propulsive Breeze', g='BDD', add=_LOW)
_set("Cloud Dragon's Cloak", g='ADD', add=_LOW)
_set('Shadow Projectile', g='BDD', add=_LOW)
_set('Unexpected Transposition', g='CDD', add=_HIGH)
_set('Spell Riposte', g='CDD', add=_HIGH)
